@Timeout(20)
class ThemeLoadDiagnosticsTest {

	@TempDir
	Path directory;

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void terminalMarkersDrainAndWatcherJoinsOnSuccessAndFailure(boolean fail) {
		List<String> output = new CopyOnWriteArrayList<>();
		Thread caller = Thread.currentThread();
		ThemeLoadDiagnostics diagnostics = diagnostics(new long[] { Long.MAX_VALUE }, output::add);
		RuntimeException workloadFailure = new IllegalArgumentException("original workload failure");
		Runnable workload = () -> {
			try (diagnostics) {
				assertSame(caller, Thread.currentThread(), "the workload is not moved to the diagnostic thread");
				ThemeLoadDiagnostics.phase("FINAL_COMMIT_BEGIN");
				if (fail) {
					ThemeLoadDiagnostics.phase("FINAL_COMMIT_THREW " + workloadFailure.getClass().getName());
					ThemeLoadDiagnostics.phase("LOAD_THREW " + workloadFailure.getClass().getName());
					throw workloadFailure;
				}
				ThemeLoadDiagnostics.phase("FINAL_COMMIT_RETURNED");
				ThemeLoadDiagnostics.phase("LOAD_RETURNED");
			}
		};
		if (fail) {
			assertSame(workloadFailure, assertThrows(IllegalArgumentException.class, workload::run));
		} else {
			workload.run();
		}
		assertFalse(diagnostics.watcherThread().isAlive());
		assertTrue(diagnostics.watcherThread().isDaemon());
		assertTrue(
				output.stream().anyMatch(line -> line.contains(fail ? "FINAL_COMMIT_THREW" : "FINAL_COMMIT_RETURNED")));
		assertTrue(output.stream().anyMatch(line -> line.contains(fail ? "LOAD_THREW" : "LOAD_RETURNED")));
		assertTrue(output.stream().anyMatch(line -> line.contains("WATCHER_STOP") && line.contains("droppedEvents=0")));
		int completedOutput = output.size();
		ThemeLoadDiagnostics.phase("OUTSIDE_SCOPE");
		assertEquals(completedOutput, output.size(), "closed scopes are removed from the caller's ThreadLocal");
	}

	@Test
	void nestedScopesRestoreTheOuterScopeAndCallerInterrupt() {
		List<String> outerOutput = new CopyOnWriteArrayList<>();
		List<String> innerOutput = new CopyOnWriteArrayList<>();
		ThemeLoadDiagnostics outer = diagnostics(new long[] { Long.MAX_VALUE }, outerOutput::add);
		try {
			try (outer) {
				ThemeLoadDiagnostics inner = diagnostics(new long[] { Long.MAX_VALUE }, innerOutput::add);
				try (inner) {
					ThemeLoadDiagnostics.phase("INNER_DONE");
				}
				assertFalse(inner.watcherThread().isAlive());
				ThemeLoadDiagnostics.phase("OUTER_RESTORED");
				Thread.currentThread().interrupt();
			}
			assertTrue(Thread.currentThread().isInterrupted(),
					"bounded join must restore the caller's original interrupt");
		} finally {
			Thread.interrupted();
		}
		assertFalse(outer.watcherThread().isAlive());
		assertTrue(outerOutput.stream().anyMatch(line -> line.contains("OUTER_RESTORED")));
		assertFalse(innerOutput.stream().anyMatch(line -> line.contains("OUTER_RESTORED")));
	}

	@Test
	void finiteSamplingCapturesVirtualCallerAndBoundsDirectoryAndOutput() throws Exception {
		Path runs = Files.createDirectory(directory.resolve(".lmdb-initial-import-runs"));
		for (int i = 0; i < 40; i++) {
			Files.createFile(runs.resolve("run-" + i));
		}
		List<String> output = new CopyOnWriteArrayList<>();
		CountDownLatch exhausted = new CountDownLatch(1);
		AtomicReference<Throwable> failure = new AtomicReference<>();
		AtomicReference<ThemeLoadDiagnostics> scope = new AtomicReference<>();
		Thread caller = Thread.ofVirtual().name("theme-diagnostic-virtual-caller").unstarted(() -> {
			try (ThemeLoadDiagnostics diagnostics = new ThemeLoadDiagnostics(directory, 1024, 2048, () -> {
				throw new IllegalStateException("optional growth counter unavailable");
			}, new long[] { 0, 0 }, TimeUnit.SECONDS.toNanos(5), line -> {
				output.add(line);
				if (line.contains("sampling budget exhausted")) {
					exhausted.countDown();
				}
			})) {
				scope.set(diagnostics);
				assertTrue(exhausted.await(10, TimeUnit.SECONDS), "the finite real sampling schedule must finish");
				ThemeLoadDiagnostics.phase("FINAL_COMMIT_RETURNED");
			} catch (Throwable caught) {
				failure.set(caught);
			}
		});
		caller.start();
		try {
			caller.join(15000);
			assertFalse(caller.isAlive());
			if (failure.get() != null) {
				throw new AssertionError("virtual caller failed", failure.get());
			}
			assertNotNull(scope.get());
			assertFalse(scope.get().watcherThread().isAlive());
			assertEquals(2, output.stream().filter(line -> line.contains("] SNAPSHOT sample=")).count());
			assertEquals(2, output.stream().filter(line -> line.contains("] FILE_SAMPLE sample=")).count());
			assertTrue(output.stream()
					.anyMatch(line -> line.contains("DIRECT_CALLER name=" + caller.getName())
							&& line.contains("virtual=true") && line.contains("other virtual threads omitted")));
			assertTrue(output.stream()
					.anyMatch(line -> line.contains("optional growth counter unavailable")
							&& line.contains("DIRECT_CALLER")),
					"an optional counter failure must not suppress the core stacks");
			assertTrue(output.stream().anyMatch(line -> line.contains("runFileEntries sampled=32 truncated=true")));
			assertTrue(output.stream().allMatch(line -> line.length() <= ThemeLoadDiagnostics.MAX_SNAPSHOT_CHARS));
			assertTrue(output.stream().anyMatch(line -> line.contains("FINAL_COMMIT_RETURNED")));
		} finally {
			if (caller.isAlive()) {
				caller.interrupt();
				caller.join(5000);
			}
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void stuckDiagnosticOutputFailsBoundedCleanupWithoutReplacingWorkloadFailure(boolean fail) throws Exception {
		CountDownLatch outputEntered = new CountDownLatch(1);
		CountDownLatch releaseOutput = new CountDownLatch(1);
		ThemeLoadDiagnostics diagnostics = new ThemeLoadDiagnostics(directory, 1, 2, () -> 0,
				new long[] { Long.MAX_VALUE }, TimeUnit.MILLISECONDS.toNanos(100), line -> {
					outputEntered.countDown();
					boolean released = false;
					while (!released) {
						try {
							releaseOutput.await();
							released = true;
						} catch (InterruptedException ignored) {
							// Deliberately model a PrintStream/filesystem call which ignores cancellation.
						}
					}
				});
		RuntimeException workloadFailure = new IllegalArgumentException("preserve this failure");
		try {
			assertTrue(outputEntered.await(10, TimeUnit.SECONDS));
			RuntimeException caught = assertThrows(RuntimeException.class, () -> {
				try (diagnostics) {
					if (fail) {
						throw workloadFailure;
					}
				}
			});
			Throwable cleanupFailure = caught;
			if (fail) {
				assertSame(workloadFailure, caught);
				assertEquals(1, caught.getSuppressed().length);
				cleanupFailure = caught.getSuppressed()[0];
			}
			assertTrue(cleanupFailure.getMessage().contains("did not terminate within cleanup budget"));
			assertTrue(diagnostics.watcherThread().isAlive(),
					"exceptional stuck daemon is reported, not called stopped");
			assertFalse(Thread.currentThread().isInterrupted(), "cleanup interrupts only its own watcher");
		} finally {
			releaseOutput.countDown();
			diagnostics.close();
			diagnostics.watcherThread().join(5000);
			assertFalse(diagnostics.watcherThread().isAlive(),
					"the test itself must not leak its deliberate stuck thread");
		}
	}

	private ThemeLoadDiagnostics diagnostics(long[] schedule, Consumer<String> output) {
		return new ThemeLoadDiagnostics(directory, 1024, 2048, () -> 0, schedule, TimeUnit.SECONDS.toNanos(5), output);
	}
}
